function LoginPage({ initialKind }: { initialKind?: 'admin' | 'customer' }) {
  const { login, user, userType, role } = useApp();
  const navigate = useNavigate();
  const location = useLocation();
  const [kind, setKind] = useState<'admin' | 'customer'>(initialKind || 'customer');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const requested = (location.state as { from?: unknown } | null)?.from;
  if (user && userType) return <Navigate to={resolveLoginDestination(userType, role, requested)} replace />;

  const submit = (event: React.FormEvent) => {
    event.preventDefault(); setError('');
    const authenticatedUser = login(email, password, kind);
    if (!authenticatedUser) {
      setError(kind === 'admin' ? 'Las credenciales no corresponden al acceso administrativo de demostración.' : 'Ingresa un correo válido y una contraseña de al menos 4 caracteres.');
      return;
    }
    navigate(resolveLoginDestination(kind, authenticatedUser.role, requested), { replace: true });
  };

  const adminMode = kind === 'admin';
  return <div className="admin-login-page"><div className="admin-login-panel"><Brand /><div className="security-pill"><ShieldCheck size={15} /> Acceso de demostración</div><div className="admin-login-copy"><span className="eyebrow">NEXO · {adminMode ? 'Administración' : 'Tienda'}</span><h1>{adminMode ? <>Haz que tu negocio<br /><em>avance.</em></> : <>Todo lo que buscas,<br /><em>en un solo lugar.</em></>}</h1><p>{adminMode ? 'Ingresa con tu cuenta de personal para continuar.' : 'Ingresa para continuar con tus compras.'}</p></div><div className="admin-login-footer"><span>© 2025 NEXO COMMERCE</span><span>Modo demostración</span></div></div><div className="admin-login-form"><Link to="/" className="back-link"><ArrowLeft size={16} /> Volver al inicio</Link><div className="admin-form-inner"><div className="admin-icon"><LockIcon /></div><h2>Iniciar sesión</h2><p>Usa tus credenciales para acceder a tu espacio.</p><form onSubmit={submit}>
    {!initialKind && <label className="field"><span>Tipo de cuenta</span><select value={kind} onChange={(event) => { setKind(event.target.value as 'admin' | 'customer'); setError(''); }}><option value="customer">Cliente</option><option value="admin">Personal administrativo</option></select></label>}
    <Field label="Correo electrónico" type="email" value={email} onChange={setEmail} placeholder={adminMode ? 'superadmin@nexo.gt' : 'tu@correo.com'} /><Field label="Contraseña" type="password" value={password} onChange={setPassword} placeholder="Ingresa tu contraseña" />
    {error && <div className="error-message" role="alert"><X size={15} />{error}</div>}<button className={`button ${adminMode ? 'button-dark' : 'button-primary'} full`} type="submit">Ingresar <ArrowRight size={16} /></button></form>
    {adminMode ? <div className="demo-hint"><span>Credenciales administrativas de demostración</span><code>superadmin@nexo.gt</code><code>Admin123!</code></div> : <p className="auth-bottom demo-login-note">Inicio de sesión de demostración. El registro de cuentas aún no está disponible.</p>}
    {initialKind && <Link className="auth-bottom login-switch" to="/access">Cambiar tipo de cuenta</Link>}
  </div></div></div>;
}

function LockIcon() { return <ShieldCheck size={25} />; }
function Field({ label, type, value, onChange, placeholder }: { label: string; type: string; value: string; onChange: (value: string) => void; placeholder: string }) { return <label className="field"><span>{label}</span><input required type={type} defaultValue={value} onChange={(e) => onChange(e.target.value)} placeholder={placeholder} /></label>; }

const adminRoleHome: Record<Role, string> = {
  superadmin: '/admin/dashboard', admin: '/admin/dashboard', sales: '/admin/sales', warehouse: '/admin/inventory', employee: '/admin/profile',
};
const adminRoleRoutes: Record<Role, string[]> = {
  superadmin: ['/admin'], admin: ['/admin'],
  sales: ['/admin/dashboard', '/admin/sales', '/admin/customers', '/admin/transfers', '/admin/payments', '/admin/invoices', '/admin/reports'],
  warehouse: ['/admin/dashboard', '/admin/inventory', '/admin/purchases', '/admin/suppliers'],
  employee: ['/admin/profile'],
};

function canVisitAdminPath(role: Role, pathname: string) {
  if (pathname.includes('\\') || /%2f|%5c/i.test(pathname) || pathname.split('/').some((segment) => segment === '.' || segment === '..')) return false;
  const moduleMap: Record<string, 'dashboard'|'products'|'inventory'|'orders'|'sales'|'customers'|'suppliers'|'reports'|'settings'|'users'> = { dashboard: 'dashboard', products: 'products', categories: 'products', inventory: 'inventory', purchases: 'inventory', orders: 'orders', sales: 'sales', customers: 'customers', suppliers: 'suppliers', reports: 'reports', settings: 'settings', users: 'users', 'roles-permissions': 'users', transfers: 'orders', payments: 'orders', invoices: 'sales', accounting: 'reports', profile: 'settings', brands: 'products' };
  const requestedModule = moduleMap[pathname.split('/').filter(Boolean)[1] || 'dashboard'];
  return Boolean(requestedModule && roleService.can(role, requestedModule, 'view'));
}

function resolveLoginDestination(kind: 'admin' | 'customer', role: Role | null, requested: unknown) {
  if (kind === 'customer') return '/store';
  const safeRole = role || 'employee';
  const requestedPath = typeof requested === 'string' ? requested : requested && typeof requested === 'object' && 'pathname' in requested ? (requested as { pathname?: unknown }).pathname : undefined;
  if (typeof requestedPath === 'string' && requestedPath.startsWith('/admin/') && canVisitAdminPath(safeRole, requestedPath)) {
    const search = requested && typeof requested === 'object' && 'search' in requested && typeof requested.search === 'string' && requested.search.startsWith('?') ? requested.search : '';
    const hash = requested && typeof requested === 'object' && 'hash' in requested && typeof requested.hash === 'string' && requested.hash.startsWith('#') ? requested.hash : '';
    return `${requestedPath}${search}${hash}`;
  }
  return adminRoleHome[safeRole];
}

function PublicShell({ children }: { children: React.ReactNode }) { return <div className="public-app"><PublicHeader />{children}</div>; }

function Store() {
  const [search, setSearch] = useState(''); const [category, setCategory] = useState('Todos'); const [sort, setSort] = useState('featured'); const [page, setPage] = useState(1); const [catalog, setCatalog] = useState<Product[]>(products); const [source, setSource] = useState<'api' | 'fallback'>('fallback'); const [loading, setLoading] = useState(true);
  useEffect(() => { fetchCatalogFromApi().then((result) => { setCatalog([...products, ...result.products]); setSource(result.source); }).finally(() => setLoading(false)); }, []);
  const availableCategories = ['Todos', ...Array.from(new Set(catalog.map((product) => product.category)))];
  const filtered = useMemo(() => catalog.filter((product) => (category === 'Todos' || product.category === category) && product.name.toLowerCase().includes(search.toLowerCase())).sort((a, b) => sort === 'price-low' ? a.price - b.price : sort === 'price-high' ? b.price - a.price : Number(b.featured) - Number(a.featured)), [catalog, category, search, sort]);
  useEffect(() => { setPage(1); }, [search, category, sort]);
  const pageSize = 24; const totalPages = Math.max(1, Math.ceil(filtered.length / pageSize)); const visibleProducts = filtered.slice((page - 1) * pageSize, page * pageSize);
  return <PublicShell><main className="store-page"><section className="store-hero"><div><span className="eyebrow">Selección NEXO · septiembre 2025</span><h1>Encuentra algo<br /><em>que te inspire.</em></h1><p>Productos útiles, bonitos y elegidos para acompañarte todos los días.</p></div><div className="store-hero-badge"><Sparkles size={17} /><span>{source === 'api' ? 'Catálogo actualizado' : 'Catálogo demo'}</span><strong>{catalog.length}+ productos</strong></div></section><section className="store-toolbar"><div className="search-box"><Search size={18} /><input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Buscar productos..." />{search && <button onClick={() => setSearch('')}><X size={16} /></button>}</div><div className="category-pills">{availableCategories.map((item) => <button key={item} className={category === item ? 'active' : ''} onClick={() => setCategory(item)}>{item}</button>)}</div><label className="sort-select"><SlidersHorizontal size={16} /><select value={sort} onChange={(e) => setSort(e.target.value)}><option value="featured">Destacados</option><option value="price-low">Precio menor</option><option value="price-high">Precio mayor</option></select><ChevronDown size={15} /></label></section><div className="catalog-meta"><span>{loading ? 'Cargando catálogo...' : `${filtered.length} productos · página ${page} de ${totalPages}`}</span><span className="catalog-tip"><Sparkles size={14} /> {source === 'api' ? 'Datos desde DummyJSON' : 'Modo offline demo'}</span></div>{visibleProducts.length > 0 ? <><div className="product-grid">{visibleProducts.map((product) => <ProductCard key={product.id} product={product} />)}</div><div className="catalog-pagination"><button disabled={page === 1} onClick={() => setPage((current) => current - 1)}><ChevronLeft size={16} /> Anterior</button><span>Página <strong>{page}</strong> de {totalPages}</span><button disabled={page === totalPages} onClick={() => setPage((current) => current + 1)}>Siguiente <ChevronRight size={16} /></button></div></> : <EmptyState search={search} />}</main></PublicShell>;
}

function EmptyState({ search }: { search: string }) { return <div className="empty-state"><Search size={30} /><h3>No encontramos resultados</h3><p>Prueba con otra búsqueda{search ? ` diferente a “${search}”` : ''}.</p></div>; }

function ProductCard({ product }: { product: Product }) { const { addToCart } = useApp(); const [added, setAdded] = useState(false); const click = () => { if (!product.stock) return; addToCart(product); setAdded(true); setTimeout(() => setAdded(false), 1400); }; return <article className="product-card"><Link to={`/product/${product.id}`} className="product-image-wrap"><img src={product.image} alt={product.name} />{product.compareAt && <span className="sale-tag">Oferta</span>}{product.status === 'Bajo stock' && <span className="stock-tag">Últimas unidades</span>}<span className="quick-view">Ver producto <ArrowUpRight size={14} /></span></Link><div className="product-info"><span className="product-category">{product.category}</span><Link to={`/product/${product.id}`}><h3>{product.name}</h3></Link><div className="product-bottom"><div><strong>{formatQ(product.price)}</strong>{product.compareAt && <del>{formatQ(product.compareAt)}</del>}</div><button className={added ? 'add-button added' : 'add-button'} disabled={!product.stock} onClick={click}>{added ? <Check size={17} /> : <Plus size={18} />}</button></div></div></article>; }

function ProductDetailApi() { const { id } = useParams(); const [catalog, setCatalog] = useState<Product[]>(products); const { addToCart } = useApp(); const navigate = useNavigate(); const [quantity, setQuantity] = useState(1); const [added, setAdded] = useState(false); useEffect(() => { fetchCatalogFromApi().then((result) => setCatalog([...products, ...result.products])); }, []); const product = catalog.find((item) => item.id === id) || products[0]; const add = () => { for (let i = 0; i < quantity; i += 1) addToCart(product); setAdded(true); }; return <PublicShell><main className="detail-page"><Link to="/store" className="back-link"><ArrowLeft size={16} /> Volver al catálogo</Link><div className="detail-layout"><div className="detail-image"><img src={product.image} alt={product.name} />{product.compareAt && <span className="sale-tag">Oferta especial</span>}</div><div className="detail-copy"><span className="eyebrow">{product.category} · {product.sku}</span><h1>{product.name}</h1><div className="detail-price"><strong>{formatQ(product.price)}</strong>{product.compareAt && <del>{formatQ(product.compareAt)}</del>}<span>{product.compareAt ? `Ahorra ${formatQ(product.compareAt - product.price)}` : 'Precio especial'}</span></div><p>{product.description}</p><div className="detail-stock"><span className={product.stock < 10 ? 'orange-dot' : 'green-dot'} />{product.stock ? `${product.stock} unidades disponibles` : 'Producto agotado'}</div><div className="detail-buy"><div className="quantity"><button onClick={() => setQuantity(Math.max(1, quantity - 1))}><Minus size={15} /></button><span>{quantity}</span><button onClick={() => setQuantity(Math.min(product.stock || 1, quantity + 1))}><Plus size={15} /></button></div><button className="button button-primary" disabled={!product.stock} onClick={add}>{added ? <><Check size={17} /> Agregado al carrito</> : <><ShoppingCart size={17} /> Agregar al carrito</>}</button></div>{added && <button className="text-link detail-go-cart" onClick={() => navigate('/cart')}>Ir al carrito <ArrowRight size={16} /></button>}<div className="detail-benefits"><div><Truck size={17} /><span>Envío nacional<br /><small>2–4 días hábiles</small></span></div><div><ShieldCheck size={17} /><span>Compra segura<br /><small>Datos protegidos</small></span></div><div><RefreshIcon /><span>Devolución fácil<br /><small>30 días</small></span></div></div></div></div><section className="related"><div className="section-heading"><div><span className="eyebrow">También te puede gustar</span><h2>Más para descubrir</h2></div><Link to="/store" className="text-link">Ver catálogo completo <ArrowRight size={16} /></Link></div><div className="product-grid related-grid">{catalog.filter((p) => p.id !== product.id).slice(0, 4).map((p) => <ProductCard key={p.id} product={p} />)}</div></section></main></PublicShell>; }

function ProductDetail() { const { id } = useParams(); const product = products.find((item) => item.id === id) || products[0]; const { addToCart } = useApp(); const navigate = useNavigate(); const [quantity, setQuantity] = useState(1); const [added, setAdded] = useState(false); const add = () => { for (let i = 0; i < quantity; i += 1) addToCart(product); setAdded(true); }; return <PublicShell><main className="detail-page"><Link to="/store" className="back-link"><ArrowLeft size={16} /> Volver al catálogo</Link><div className="detail-layout"><div className="detail-image"><img src={product.image} alt={product.name} />{product.compareAt && <span className="sale-tag">Oferta especial</span>}</div><div className="detail-copy"><span className="eyebrow">{product.category} · {product.sku}</span><h1>{product.name}</h1><div className="detail-price"><strong>{formatQ(product.price)}</strong>{product.compareAt && <del>{formatQ(product.compareAt)}</del>}<span>Ahorra {product.compareAt ? formatQ(product.compareAt - product.price) : ''}</span></div><p>{product.description}</p><div className="detail-stock"><span className={product.stock < 10 ? 'orange-dot' : 'green-dot'} />{product.stock ? `${product.stock} unidades disponibles` : 'Producto agotado'}</div><div className="detail-buy"><div className="quantity"><button onClick={() => setQuantity(Math.max(1, quantity - 1))}><Minus size={15} /></button><span>{quantity}</span><button onClick={() => setQuantity(Math.min(product.stock || 1, quantity + 1))}><Plus size={15} /></button></div><button className="button button-primary" disabled={!product.stock} onClick={add}>{added ? <><Check size={17} /> Agregado al carrito</> : <><ShoppingCart size={17} /> Agregar al carrito</>}</button></div>{added && <button className="text-link detail-go-cart" onClick={() => navigate('/cart')}>Ir al carrito <ArrowRight size={16} /></button>}<div className="detail-benefits"><div><Truck size={17} /><span>Envío nacional<br /><small>2–4 días hábiles</small></span></div><div><ShieldCheck size={17} /><span>Compra segura<br /><small>Datos protegidos</small></span></div><div><RefreshIcon /><span>Devolución fácil<br /><small>30 días</small></span></div></div></div></div><section className="related"><div className="section-heading"><div><span className="eyebrow">También te puede gustar</span><h2>Más para descubrir</h2></div><Link to="/store" className="text-link">Ver catálogo completo <ArrowRight size={16} /></Link></div><div className="product-grid related-grid">{products.filter((p) => p.id !== product.id).slice(0, 4).map((p) => <ProductCard key={p.id} product={p} />)}</div></section></main></PublicShell>; }
function RefreshIcon() { return <Activity size={17} />; }

function CartPage() { const { cart, cartTotal, updateQuantity, removeFromCart } = useApp(); const navigate = useNavigate(); return <PublicShell><main className="cart-page"><div className="page-title-row"><div><span className="eyebrow">Tu selección</span><h1>Mi carrito <span>({cart.length})</span></h1></div><Link to="/store" className="text-link"><ArrowLeft size={16} /> Seguir comprando</Link></div>{cart.length === 0 ? <div className="empty-state cart-empty"><ShoppingCart size={34} /><h3>Tu carrito está esperando</h3><p>Agrega productos que te gusten y aparecerán aquí.</p><Link to="/store" className="button button-primary">Explorar productos <ArrowRight size={16} /></Link></div> : <div className="cart-layout"><div className="cart-items">{cart.map((item) => <div className="cart-item" key={item.id}><img src={item.image} alt={item.name} /><div className="cart-item-info"><span>{item.category}</span><h3>{item.name}</h3><strong>{formatQ(item.price)}</strong></div><div className="quantity"><button onClick={() => updateQuantity(item.id, item.quantity - 1)}><Minus size={14} /></button><span>{item.quantity}</span><button onClick={() => updateQuantity(item.id, item.quantity + 1)}><Plus size={14} /></button></div><button className="icon-button danger" onClick={() => removeFromCart(item.id)} aria-label="Eliminar"><Trash2 size={17} /></button></div>)}</div><aside className="summary-card"><h2>Resumen del pedido</h2><div><span>Subtotal</span><strong>{formatQ(cartTotal)}</strong></div><div><span>Envío</span><strong className="free">Gratis</strong></div><div className="summary-total"><span>Total</span><strong>{formatQ(cartTotal)}</strong></div><button className="button button-primary full" onClick={() => navigate('/checkout')}>Continuar al checkout <ArrowRight size={16} /></button><small><ShieldCheck size={14} /> Compra segura y protegida</small></aside></div>}</main></PublicShell>; }

function Checkout() {
  const { cart, cartTotal, paymentMethods } = useApp();
  const navigate = useNavigate();
  const availableMethods = (['card', 'transfer'] as const).filter((method) => paymentMethods[method]);
  const [payment, setPayment] = useState<PaymentMethod>('card');
  const [done, setDone] = useState(false);
  const [paymentError, setPaymentError] = useState('');

  useEffect(() => {
    if (!paymentMethods[payment]) setPayment(availableMethods[0] || 'card');
  }, [paymentMethods, payment, availableMethods]);

  const submit = async (event: React.FormEvent) => {
    event.preventDefault(); setPaymentError('');
    if (!paymentMethods[payment]) {
      setPaymentError('Este método ya no está disponible. Elige una de las opciones activas.');
      return;
    }
    try {
      const result = await paymentService.simulate(payment);
      setDone(true);
      window.setTimeout(() => navigate('/confirmation', { state: { paymentMethod: payment, paymentStatus: result.status } }), 700);
    } catch {
      setPaymentError('Este método de pago se desactivó. Selecciona otro método activo e inténtalo de nuevo.');
    }
  };

  if (!cart.length) return <Navigate to="/cart" replace />;
  if (done) return <div className="processing"><div className="loader" /><h2>Procesando tu pedido...</h2><p>Simulación de pago en curso; no se realizará ningún cobro.</p></div>;
  return <PublicShell><main className="checkout-page"><Link to="/cart" className="back-link"><ArrowLeft size={16} /> Volver al carrito</Link><div className="checkout-heading"><div><span className="eyebrow">Último paso</span><h1>Finaliza tu pedido</h1></div><div className="checkout-steps"><span className="done"><Check size={13} /> Carrito</span><i /><span className="current">2. Checkout</span><i /><span>3. Confirmación</span></div></div>
    <form className="checkout-layout" onSubmit={submit}><div className="checkout-form"><section className="form-section"><div className="section-title"><span>01</span><div><h2>Información de entrega</h2><p>¿Dónde enviamos tu pedido?</p></div></div><div className="form-grid"><Field label="Nombre completo" type="text" value="Valeria Castillo" onChange={() => undefined} placeholder="Tu nombre" /><Field label="Teléfono" type="tel" value="+502 5555 5555" onChange={() => undefined} placeholder="5555 5555" /></div><Field label="Dirección de entrega" type="text" value="Zona 10, Ciudad de Guatemala" onChange={() => undefined} placeholder="Calle, avenida, zona" /><div className="form-grid"><Field label="Ciudad" type="text" value="Ciudad de Guatemala" onChange={() => undefined} placeholder="Ciudad" /><Field label="Referencia (opcional)" type="text" value="Cerca de Oakland Mall" onChange={() => undefined} placeholder="Una referencia" /></div></section>
    <section className="form-section"><div className="section-title"><span>02</span><div><h2>Método de pago</h2><p>Opciones disponibles · solo demostración</p></div></div><div className="payment-options">{paymentMethods.card && <button type="button" className={payment === 'card' ? 'payment-option active' : 'payment-option'} onClick={() => { if (paymentMethods.card) { setPayment('card'); setPaymentError(''); } }}><CreditCard size={19} /><span><strong>Tarjeta simulada</strong><small>No se solicitan datos de tarjeta</small></span><span className="radio" /></button>}{paymentMethods.transfer && <button type="button" className={payment === 'transfer' ? 'payment-option active' : 'payment-option'} onClick={() => { if (paymentMethods.transfer) { setPayment('transfer'); setPaymentError(''); } }}><ArrowDownToLine size={19} /><span><strong>Transferencia bancaria</strong><small>Pendiente de verificación</small></span><span className="radio" /></button>}</div>
    {!availableMethods.length ? <div className="payment-error" role="alert">No hay métodos de pago activos. Contacta al administrador antes de continuar.</div> : payment === 'card' ? <div className="transfer-hint"><CreditCard size={18} /><p>Pago de tarjeta simulado para esta demostración. <strong>No se realiza ningún cargo y no guardamos información financiera.</strong></p></div> : <div className="transfer-hint"><Wallet size={18} /><p>El pedido quedará <strong>pendiente de verificación</strong>. Esta demostración no procesa transferencias reales.</p></div>}
    {paymentError && <div className="payment-error" role="alert">{paymentError}</div>}</section></div><aside className="summary-card checkout-summary"><h2>Tu pedido</h2>{cart.map((item) => <div className="mini-line" key={item.id}><span>{item.quantity} × {item.name}</span><strong>{formatQ(item.price * item.quantity)}</strong></div>)}<div className="summary-total"><span>Total a pagar</span><strong>{formatQ(cartTotal)}</strong></div><button className="button button-primary full" type="submit" disabled={!availableMethods.length}>Confirmar pedido <ArrowRight size={16} /></button><small><ShieldCheck size={14} /> Simulación únicamente. No se realizan cargos reales.</small></aside></form></main></PublicShell>;
}

function Confirmation() {
  const location = useLocation();
  const result = location.state as { paymentMethod?: PaymentMethod; paymentStatus?: string } | null;
  const transferPending = result?.paymentMethod === 'transfer' && result.paymentStatus === 'pending_verification';
  const statusLabel = transferPending ? 'Pendiente de verificación' : result?.paymentStatus === 'approved' ? 'Pago simulado' : 'Demostración';
  return <PublicShell><main className="confirmation"><div className="success-icon"><Check size={34} /></div><span className="eyebrow">Demostración</span><h1>{transferPending ? <>Pedido recibido<br /><em>pendiente.</em></> : <>Simulación<br /><em>completada.</em></>}</h1><p>{transferPending ? 'La transferencia simulada queda pendiente de verificación. No se procesó ningún pago real.' : 'El flujo de tarjeta se simuló correctamente. No se creó una transacción ni se realizó ningún cobro.'}</p><div className="confirmation-card"><div><span>Estado</span><strong>{statusLabel}</strong></div><div><span>Total de demostración</span><strong>Q 1,284.00</strong></div><div><span>Referencia ficticia</span><strong>#NX-1049</strong></div></div><div className="landing-actions"><Link to="/store" className="button button-primary">Seguir comprando <ArrowRight size={16} /></Link></div></main></PublicShell>;
}

function AdminShell({ children }: { children: React.ReactNode }) { const { user, logout, role } = useApp(); const location = useLocation(); const navigate = useNavigate(); const [mobile, setMobile] = useState(false); const navItems = [{ label: 'Resumen', icon: LayoutDashboard, path: '/admin/dashboard' }, { label: 'Catálogo', icon: Package, path: '/admin/products' }, { label: 'Marcas', icon: Tag, path: '/admin/brands' }, { label: 'Proveedores', icon: Truck, path: '/admin/suppliers' }, { label: 'Ventas', icon: CircleDollarSign, path: '/admin/sales' }, { label: 'Contabilidad', icon: Wallet, path: '/admin/accounting' }, { label: 'Inventario', icon: Boxes, path: '/admin/inventory' }, { label: 'Clientes', icon: Users, path: '/admin/customers' }]; const manage = [{ label: 'Compras de mercancía', icon: Package, path: '/admin/purchases' }, { label: 'Transferencias', icon: ArrowDownToLine, path: '/admin/transfers' }, { label: 'Usuarios', icon: UserCircle, path: '/admin/users' }, { label: 'Reportes', icon: BarChart3, path: '/admin/reports' }]; const isActive = (path: string) => location.pathname === path || (path === '/admin/products' && location.pathname.includes('/admin/categories')); const links = (items: typeof navItems) => items.filter(({ path }) => { const key = path.split('/')[2]; const map: Record<string, 'dashboard'|'products'|'inventory'|'orders'|'sales'|'customers'|'suppliers'|'reports'|'settings'|'users'> = { dashboard:'dashboard', products:'products', brands:'products', suppliers:'suppliers', sales:'sales', accounting:'reports', inventory:'inventory', customers:'customers', purchases:'inventory', transfers:'orders', users:'users', reports:'reports' }; return Boolean(role && roleService.can(role, map[key] || 'dashboard', 'view')); }).map(({ label, icon: NavIcon, path }) => <Link key={path} to={path} className={isActive(path) ? 'side-link active' : 'side-link'} onClick={() => setMobile(false)}><NavIcon size={17} /><span>{label}</span></Link>); return <div className="admin-app"><aside className={mobile ? 'admin-sidebar mobile-open' : 'admin-sidebar'}><div className="side-top"><Brand /><button className="close-mobile" onClick={() => setMobile(false)}><X size={20} /></button></div><div className="workspace-selector"><span className="workspace-logo">N</span><div><strong>NEXO Commerce</strong><small>Operación principal</small></div><ChevronDown size={15} /></div><nav><span className="side-label">Principal</span>{links(navItems)}<span className="side-label">Gestionar</span>{links(manage)}<span className="side-label">Sistema</span><Link to="/admin/settings" className={isActive('/admin/settings') ? 'side-link active' : 'side-link'}><Settings size={17} /><span>Configuración</span></Link></nav><div className="side-bottom"><div className="help-card"><Sparkles size={18} /><strong>¿Necesitas ayuda?</strong><span>Visita nuestro centro de soporte</span><a href="#help">Ir al centro <ArrowUpRight size={14} /></a></div><button className="user-mini" onClick={() => navigate('/admin/profile')}><span className="avatar">MF</span><span><strong>{user?.name || 'María Fernanda'}</strong><small>Súper Administrador</small></span><MoreDots /></button></div></aside><div className="admin-content"><header className="admin-header"><button className="mobile-menu" onClick={() => setMobile(true)}><Menu size={20} /></button><div className="admin-breadcrumb"><span>Panel</span><ChevronRight size={14} /><strong>{getModuleLabel(location.pathname)}</strong></div><div className="admin-header-actions"><button className="user-header" onClick={() => navigate('/admin/profile')}><span className="avatar">MF</span><span><strong>{user?.name || 'María Fernanda'}</strong><small>Súper Administrador</small></span><ChevronDown size={15} /></button><button className="logout-button" onClick={() => { logout(); navigate('/'); }}><LogOut size={17} /></button></div></header><div className="admin-main">{children}</div></div></div>; }
function MoreDots() { return <span className="more-dots">•••</span>; }
function getModuleLabel(path: string) { const labels: Record<string, string> = { dashboard: 'Resumen', products: 'Productos', brands: 'Marcas', categories: 'Categorías', sales: 'Ventas', inventory: 'Inventario', customers: 'Clientes', transfers: 'Transferencias', users: 'Usuarios', reports: 'Reportes', purchases: 'Compras de mercancía', accounting: 'Contabilidad', settings: 'Configuración', profile: 'Mi perfil', invoices: 'Facturación', payments: 'Pagos', suppliers: 'Proveedores', 'roles-permissions': 'Roles y permisos' }; return labels[path.split('/')[2]] || 'Resumen'; }

function AdminPage() { const { '*': section = 'dashboard' } = useParams(); return <AdminShell>{section === 'dashboard' ? <Dashboard /> : section === 'accounting' ? <AccountingPage /> : section === 'purchases' ? <PurchasesPage /> : section === 'sales' ? <SalesPage /> : section === 'brands' ? <BrandsPage /> : section === 'suppliers' ? <SuppliersPage /> : section === 'roles-permissions' ? <RolesPermissionsPage /> : section === 'orders' ? <Navigate to="/admin/dashboard" replace /> : section === 'settings' ? <><PaymentMethodsSettings /><ModulePage section={section} /></> : <ModulePage section={section} />}</AdminShell>; }

function PaymentMethodsSettings() {
  const { paymentMethods, updatePaymentMethod } = useApp();
  const [pending, setPending] = useState(false);
  const [feedback, setFeedback] = useState('');
  const [error, setError] = useState('');
  const options = [
    { id: 'card' as const, label: 'Tarjeta simulada', description: 'Opción de demostración. No solicita ni guarda datos de tarjeta.', Icon: CreditCard },
    { id: 'transfer' as const, label: 'Transferencia bancaria', description: 'El pedido queda pendiente de verificación manual.', Icon: ArrowDownToLine },
  ];
  const toggle = async (method: 'card' | 'transfer') => {
    setPending(true); setError(''); setFeedback('');
    try {
      const next = await updatePaymentMethod(method, !paymentMethods[method]);
      setFeedback(`${options.find((option) => option.id === method)?.label} ${next[method] ? 'activado' : 'desactivado'}. El cambio ya se guardó en este navegador.`);
    } catch {
      setError('Debe quedar al menos un método de pago activo.');
    } finally { setPending(false); }
  };
  return <section className="panel payment-settings"><div className="panel-heading"><div><h2>Métodos de pago del sitio</h2><span>Elige cuáles opciones estarán disponibles en el checkout público.</span></div></div>
    <div className="payment-settings-list">{options.map(({ id, label, description, Icon }) => <article className="payment-setting" key={id}><span className="payment-setting-icon"><Icon size={19} /></span><div className="payment-setting-copy"><strong>{label}</strong><span>{description}</span></div><span className={`payment-setting-status ${paymentMethods[id] ? 'active' : ''}`}>{paymentMethods[id] ? 'Activo' : 'Inactivo'}</span><button type="button" role="switch" aria-checked={paymentMethods[id]} aria-label={`${paymentMethods[id] ? 'Desactivar' : 'Activar'} ${label}`} className={`payment-switch ${paymentMethods[id] ? 'on' : ''}`} disabled={pending} onClick={() => void toggle(id)}><span /></button></article>)}</div>
    {feedback && <p className="payment-settings-feedback" role="status">{feedback}</p>}{error && <p className="payment-settings-error" role="alert">{error}</p>}
    <p className="payment-settings-note"><ShieldCheck size={15} /> Los métodos solo simulan el flujo: no se realizan cobros reales ni se solicitan datos de tarjeta.</p>
  </section>;
}

function Dashboard() { const [period, setPeriod] = useState('Últimos 30 días'); const { reportLowStock } = useApp(); useEffect(() => { productInventoryService.list().then(reportLowStock).catch(() => undefined); }, [reportLowStock]); return <div className="dashboard"><div className="admin-page-heading"><div><span className="eyebrow">Domingo, 14 de septiembre de 2025</span><h1>Buenos días, María <span>✦</span></h1><p>Aquí tienes un vistazo de lo que está pasando hoy.</p></div><div className="heading-actions"><button className="button button-outline"><Download size={16} /> Exportar</button><button className="period-select">{period} <ChevronDown size={15} /></button></div></div><div className="metric-grid"><Metric title="Ventas totales" value="Q 48,290.00" change="18.4%" positive icon={CircleDollarSign} tone="blue" /><Metric title="Pedidos" value="128" change="12.8%" positive icon={ShoppingBag} tone="purple" /><Metric title="Clientes nuevos" value="64" change="8.2%" positive icon={Users} tone="green" /><Metric title="Ticket promedio" value="Q 377.27" change="2.4%" positive icon={BarChart3} tone="orange" /></div><div className="dashboard-grid"><section className="panel sales-panel"><div className="panel-heading"><div><h2>Rendimiento de ventas</h2><span>Ventas netas durante el periodo seleccionado</span></div><select value={period} onChange={(e) => setPeriod(e.target.value)}><option>Últimos 30 días</option><option>Últimos 7 días</option><option>Este año</option></select></div><div className="chart-legend"><span><i className="legend-blue" /> Ventas</span><span><i className="legend-lime" /> Pedidos</span></div><SalesChart /></section><section className="panel inventory-panel"><div className="panel-heading"><div><h2>Estado del inventario</h2><span>Distribución actual de productos</span></div><Link to="/admin/inventory" className="panel-link">Ver inventario <ArrowUpRight size={14} /></Link></div><div className="donut-wrap"><div className="donut"><div><strong>156</strong><span>productos</span></div></div><div className="donut-legend"><span><i className="dot blue-bg" /> En stock <b>124</b></span><span><i className="dot lime-bg" /> Bajo stock <b>24</b></span><span><i className="dot orange-bg" /> Agotados <b>8</b></span></div></div><div className="inventory-alert"><div><span className="warning-icon">!</span><span><strong>8 productos agotados</strong><small>Requieren atención inmediata</small></span></div><Link to="/admin/inventory/alerts">Revisar <ArrowRight size={14} /></Link></div></section></div><div className="dashboard-grid bottom-grid"><section className="panel activity-panel"><div className="panel-heading"><div><h2>Actividad reciente</h2><span>Últimos movimientos en la plataforma</span></div><button className="icon-button"><MoreDots /></button></div><div className="activity-list">{activities.map((item) => <div className="activity-item" key={item.title}><span className={`activity-icon ${item.tone}`}><Icon name={item.icon} size={16} /></span><div><strong>{item.title}</strong><span>{item.description}</span></div><time>{item.time}</time></div>)}</div></section></div></div>; }
function Metric({ title, value, change, positive, icon: MetricIcon, tone }: { title: string; value: string; change: string; positive: boolean; icon: typeof CircleDollarSign; tone: string }) { return <div className="metric-card"><div className={`metric-icon ${tone}`}><MetricIcon size={20} /></div><div className="metric-content"><span>{title}</span><strong>{value}</strong><small className={positive ? 'positive' : 'negative'}><ArrowUpRight size={13} /> {change} <em>vs. periodo anterior</em></small></div><div className="metric-spark"><span /><span /><span /><span /><span /><span /></div></div>; }
function SalesChart() { return <div className="sales-chart"><div className="y-axis"><span>Q 50k</span><span>Q 40k</span><span>Q 30k</span><span>Q 20k</span><span>Q 10k</span><span>Q 0</span></div><div className="chart-body"><div className="grid-lines"><i /><i /><i /><i /><i /><i /></div><svg viewBox="0 0 700 220" preserveAspectRatio="none" aria-label="Gráfico de ventas"><defs><linearGradient id="chartFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stopColor="#9fbaf1" stopOpacity=".44" /><stop offset="100%" stopColor="#9fbaf1" stopOpacity="0" /></linearGradient></defs><path d="M0,176 C35,168 48,140 76,151 S115,163 145,122 S186,132 215,117 S260,75 286,94 S321,90 346,112 S386,91 414,67 S452,90 482,66 S512,93 540,80 S574,39 602,56 S642,27 700,22 L700,220 L0,220Z" fill="url(#chartFill)" /><path d="M0,176 C35,168 48,140 76,151 S115,163 145,122 S186,132 215,117 S260,75 286,94 S321,90 346,112 S386,91 414,67 S452,90 482,66 S512,93 540,80 S574,39 602,56 S642,27 700,22" fill="none" stroke="#3d568f" strokeWidth="3" strokeLinecap="round" /></svg><div className="x-axis"><span>16 ago</span><span>21 ago</span><span>26 ago</span><span>31 ago</span><span>5 sep</span><span>10 sep</span><span>14 sep</span></div></div></div>; }

