function ProtectedAdmin() {
  const { user, userType, role } = useApp();
  const location = useLocation();
  if (!user || !userType) return <Navigate to="/access" replace state={{ from: location }} />;
  if (userType !== 'admin') return <Navigate to={resolveLoginDestination(userType, role, null)} replace />;
  if (!role || !canVisitAdminPath(role, location.pathname)) return <Navigate to={resolveLoginDestination('admin', role, null)} replace />;
  return <Routes><Route path="*" element={<AdminPage />} /></Routes>;
}

function AdminAlertHost() {
  const { adminAlert, dismissAdminAlert } = useApp();
  const navigate = useNavigate();
  const closeRef = useRef<HTMLButtonElement>(null);
  const previousFocus = useRef<HTMLElement | null>(null);
  useEffect(() => {
    if (!adminAlert) return;
    previousFocus.current = document.activeElement instanceof HTMLElement ? document.activeElement : null;
    closeRef.current?.focus();
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') { event.preventDefault(); dismissAdminAlert(); }
      if (event.key === 'Tab') {
        const dialog = document.querySelector<HTMLElement>('.admin-alert-dialog');
        const focusable = dialog?.querySelectorAll<HTMLElement>('button:not(:disabled), a[href]');
        if (!focusable?.length) return;
        const first = focusable[0]; const last = focusable[focusable.length - 1];
        if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); }
        else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
      }
    };
    window.addEventListener('keydown', onKeyDown);
    return () => { window.removeEventListener('keydown', onKeyDown); previousFocus.current?.focus(); };
  }, [adminAlert, dismissAdminAlert]);
  if (!adminAlert) return null;
  const close = () => dismissAdminAlert();
  return <div className="admin-alert-backdrop"><section className={`admin-alert-dialog ${adminAlert.type}`} role="alertdialog" aria-modal="true" aria-labelledby="admin-alert-title" aria-describedby="admin-alert-description"><div className={`admin-alert-icon ${adminAlert.type}`} aria-hidden="true">{adminAlert.type === 'warning' ? '!' : adminAlert.type === 'success' ? '✓' : 'i'}</div><div className="admin-alert-content"><span className="eyebrow">{adminAlert.type === 'warning' ? 'Advertencia' : adminAlert.type === 'success' ? 'Operación completada' : 'Actualización'}</span><h2 id="admin-alert-title">{adminAlert.title}</h2><p className="admin-alert-entity">{adminAlert.entity}</p><p id="admin-alert-description">{adminAlert.message}</p><p className="admin-alert-next"><strong>Siguiente acción:</strong> {adminAlert.nextAction}</p><div className="admin-alert-actions"><button type="button" className="button button-outline" ref={closeRef} onClick={close}>Cerrar</button>{adminAlert.actionTo && <button type="button" className="button button-primary" onClick={() => { close(); navigate(adminAlert.actionTo!); }}>Ir al módulo</button>}</div></div></section></div>;
}

export default function App() { return <><AdminAlertHost /><Routes><Route path="/" element={<Landing />} /><Route path="/access" element={<Access />} /><Route path="/customer/login" element={<CustomerLogin />} /><Route path="/admin/login" element={<AdminLogin />} /><Route path="/store" element={<Store />} /><Route path="/product/:id" element={<ProductDetailApi />} /><Route path="/cart" element={<CartPage />} /><Route path="/checkout" element={<Checkout />} /><Route path="/confirmation" element={<Confirmation />} /><Route path="/admin/*" element={<ProtectedAdmin />} /><Route path="*" element={<Navigate to="/" replace />} /></Routes></>; }
